parameters.jsCode:
// Get the OpenAI response
const output = $json.output;

// Validate the basic OpenAI response structure
if (!Array.isArray(output) || output.length === 0) {
  throw new Error('AI response is missing output.');
}

const message = output[0];

if (!Array.isArray(message.content) || message.content.length === 0) {
  throw new Error('AI response is missing message content.');
}

// Find the output_text content
const textBlock = message.content.find(
  item => item.type === 'output_text'
);

if (!textBlock || !textBlock.text) {
  throw new Error('AI response does not contain output_text.');
}

let rawText = textBlock.text.trim();

// Remove accidental Markdown JSON fences
rawText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// Parse the AI JSON
let draft;

try {
  draft = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    `Supplier dispute AI response is not valid JSON: ${error.message}`
  );
}

// Validate required fields
if (
  typeof draft.subject !== 'string' ||
  draft.subject.trim() === ''
) {
  throw new Error('Supplier dispute draft is missing a valid subject.');
}

if (
  typeof draft.body !== 'string' ||
  draft.body.trim() === ''
) {
  throw new Error('Supplier dispute draft is missing a valid body.');
}

// Clean values
let subject = draft.subject.trim();
let body = draft.body.trim();

// Remove common AI-generated signature placeholders
body = body
  .replace(/\[Your Name\]/gi, '')
  .replace(/\[Your Position\]/gi, '')
  .replace(/\[Your Contact Information\]/gi, '')
  .replace(/\[Your Company Name\]/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Basic size protection
if (subject.length > 200) {
  throw new Error('Generated email subject is unexpectedly long.');
}

if (body.length > 5000) {
  throw new Error('Generated email body is unexpectedly long.');
}

// Retrieve the verified context from the Prepare node
const context =
  $('Prepare - Supplier Dispute Email Context').item.json;

// Final validated output
return {
  approval_id: context.approval_id,
  organization_id: context.organization_id,
  invoice_id: context.invoice_id,
  invoice_number: context.invoice_number,

  supplier_name: context.supplier_name,
  supplier_contact_name: context.supplier_contact_name,
  supplier_email: context.supplier_email,

  anomaly_type: context.anomaly_type,
  severity: context.severity,
  currency: context.currency,
  financial_impact: context.financial_impact,

  email_subject: subject,
  email_body: body,

  draft_status: 'READY_FOR_REVIEW',
  generated_by: 'AI',
  validated: true
};

